const unconverted = $('Fetch Unconverted Leads').all() || [];
const inactive = $('Fetch Inactive Members').all() || [];
const recentTrials = $('Fetch Recent Trial Classes').all() || [];

// Categorize actions needed
const actions = [];

// 1. Follow up leads who haven't booked a trial
for (const lead of unconverted) {
  const daysSinceCreated = Math.floor((Date.now() - new Date(lead.json.created_at).getTime()) / (24 * 60 * 60 * 1000));
  if (daysSinceCreated === 2 || daysSinceCreated === 5 || daysSinceCreated === 10) {
    actions.push({
      type: 'followup_lead',
      lead: lead.json,
      days_since: daysSinceCreated,
      message_template: daysSinceCreated === 2 ? 'gentle_reminder' : (daysSinceCreated === 5 ? 'social_proof' : 'last_chance')
    });
  }
}

// 2. Post-trial follow up (convert to membership)
for (const trial of recentTrials) {
  const daysSinceTrial = Math.floor((Date.now() - new Date(trial.json.booking_datetime).getTime()) / (24 * 60 * 60 * 1000));
  if (daysSinceTrial >= 1 && daysSinceTrial <= 3) {
    actions.push({
      type: 'post_trial_followup',
      trial: trial.json,
      days_since: daysSinceTrial,
      message_template: daysSinceTrial === 1 ? 'day_after_trial' : 'membership_offer'
    });
  }
}

// 3. Re-engage inactive members
for (const member of inactive) {
  const daysSinceActive = Math.floor((Date.now() - new Date(member.json.updated_at).getTime()) / (24 * 60 * 60 * 1000));
  if (daysSinceActive >= 14 && daysSinceActive <= 30) {
    actions.push({
      type: 'reactivate_member',
      member: member.json,
      days_inactive: daysSinceActive,
      message_template: 'we_miss_you'
    });
  }
}

return {
  json: {
    date: new Date().toISOString().split('T')[0],
    total_actions: actions.length,
    followup_leads: actions.filter(a => a.type === 'followup_lead').length,
    post_trial: actions.filter(a => a.type === 'post_trial_followup').length,
    reactivation: actions.filter(a => a.type === 'reactivate_member').length,
    actions
  }
};

